import { Sequelize, DataTypes } from 'sequelize';
import { sequelize } from '../config/db.js';

/**
 * Reference table for status labels.
 *
 * The timeline shows a label for every recorded status. For a Shipment Request
 * Status that label is generated by the workflow and is not editable; for a
 * Shipment Status the staff member who set the status writes it. Keeping the
 * first case in the database rather than in the view means the wording used on
 * the timeline is the same wording used everywhere else a request status is
 * shown, and changing it is one row rather than every page that prints it.
 *
 * The rows are seeded from the Status Source of Truth on every start-up, so the
 * table cannot drift from the approved vocabularies: a status that leaves the
 * approved list keeps its row but is no longer offered, and a new approved
 * status is inserted.
 */
const StatusReference = sequelize.define(
  'StatusReference',
  {
    id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true },
    // Which vocabulary this row belongs to. The two are kept apart here because
    // they are two different sequences: a timeline entry says which one it came
    // from, and a status is only meaningful against its own type.
    statusType: { type: DataTypes.ENUM('Shipment Request', 'Shipment', 'Item'), allowNull: false },
    status: { type: DataTypes.STRING(120), allowNull: false },
    // The label the workflow generates. Null for a Shipment Status, where the
    // staff member who set the status supplies the text instead.
    label: { type: DataTypes.STRING(255), allowNull: true, defaultValue: null },
    visibility: { type: DataTypes.ENUM('Customer Visible', 'Internal Only'), allowNull: false },
    // True where the label is the system's and cannot be edited by staff.
    isSystemLabel: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: false },
  },
  {
    tableName: 'status_reference',
    timestamps: true,
    underscored: true,
    indexes: [{ unique: true, fields: ['status_type', 'status'] }],
  }
);

export default StatusReference;
